    if !isempty(rest)
        if haskey(choices.leaf_nodes, first)
            error("Tried to create assignment at $first but there was already a value there.")
        end
        if !haskey(choices.internal_nodes, first)
            choices.internal_nodes[first] = DynamicChoiceMap()
        end
        set_submap!(choices.internal_nodes[first], rest, new_node)
    else
        if haskey(choices.internal_nodes, first)
            error("Tried to create value at $first but there was already a sub-assignment there.")
        end
        choices.leaf_nodes[first] = new_node
    end
